import React, { useState, useEffect } from 'react';

function Analytics() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState("ALL");

  useEffect(() => {
    fetch('http://localhost:5000/api/analytics')
      .then(res => res.json())
      .then(d => {
        console.log("Fetched Data:", d); // Check your console to see if 'uavs' is there
        setData(d);
        setLoading(false);
      })
      .catch(err => {
        console.error(err);
        setLoading(false);
      });
  }, []);

  if (loading) return <p>Loading...</p>;
  if (!data) return <p>No data from server.</p>;

  // ✅ FUZZY FILTER: Matches 'Pass' with 'Passed' and 'Fail' with 'Failed'
  const filteredUAVs = (data.uavs || []).filter(u => {
    if (filter === "ALL") return true;
    const uStatus = String(u.status || "").toLowerCase();
    const activeFilter = String(filter).toLowerCase();
    return uStatus.includes(activeFilter.substring(0, 4)); 
  });

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial' }}>
      <h2>Quality Analytics Dashboard</h2>

      {/* TOP PANELS */}
      <div style={{ display: 'flex', gap: '20px', marginBottom: '20px' }}>
        <div style={{ flex: 1, border: '1px solid #ddd', padding: '15px', borderRadius: '8px' }}>
          <h3>First Pass Yield (FPY)</h3>
          <h2 style={{ color: 'orange' }}>{data.yieldRate || 0}%</h2>
          <p>Target: 95.0%</p>
        </div>
        <div style={{ flex: 2, border: '1px solid #ddd', padding: '15px', borderRadius: '8px' }}>
          <h3>Process Health</h3>
          <p>Current system is <b>{data.yieldRate > 80 ? 'STABLE' : 'REQUIRES ATTENTION'}</b></p>
          <div style={{ width: '100%', background: '#eee', height: '10px', borderRadius: '5px' }}>
            <div style={{ width: `${data.yieldRate || 0}%`, background: 'green', height: '100%', borderRadius: '5px' }} />
          </div>
        </div>
      </div>

      {/* KPI CARDS */}
      <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
        {[
          { label: 'Total', val: data.total, col: 'black', type: 'ALL' },
          { label: 'Passed', val: data.passed, col: 'green', type: 'Pass' },
          { label: 'Failed', val: data.failed, col: 'red', type: 'Fail' },
          { label: 'In Progress', val: data.inProgress, col: 'orange', type: 'In Progress' },
        ].map(k => (
          <div key={k.label} onClick={() => setFilter(k.type)} style={{
            flex: 1, textAlign: 'center', padding: '10px', border: `2px solid ${k.col}`,
            borderRadius: '8px', cursor: 'pointer', background: filter === k.type ? '#f9f9f9' : 'white'
          }}>
            <h2 style={{ color: k.col }}>{k.val}</h2>
            <p>{k.label}</p>
          </div>
        ))}
      </div>

      <div style={{ display: 'flex', gap: '20px' }}>
        {/* LIST TABLE */}
        <div style={{ flex: 1 }}>
          <h3>UAV Status List ({filter})</h3>
          <table width="100%" border="1" style={{ borderCollapse: 'collapse' }}>
            <thead style={{ background: '#eee' }}>
              <tr><th>UAV ID</th><th>Status</th></tr>
            </thead>
            <tbody>
              {filteredUAVs.length === 0 ? (
                <tr><td colSpan="2" style={{ textAlign: 'center', padding: '10px' }}>No records found</td></tr>
              ) : (
                filteredUAVs.map(u => (
                  <tr key={u.id}>
                    <td style={{ padding: '8px' }}>{u.id}</td>
                    <td style={{ padding: '8px', fontWeight: 'bold' }}>{u.status}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* DEFECT CHART */}
        <div style={{ flex: 1 }}>
          <h3>Defect Distribution</h3>
          {(data.stageData || []).map(s => (
            <div key={s.name} style={{ marginBottom: '10px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span>{s.name}</span>
                <span>{s.defects} Defects</span>
              </div>
              <div style={{ width: '100%', background: '#eee', height: '8px' }}>
                <div style={{ width: `${Math.min(s.defects * 10, 100)}%`, background: '#007bff', height: '100%' }} />
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Analytics;
